const actor:WorkContext={userId:'reviewer',name:'Reviewer',email:'reviewer@example.test',assignmentId:'assignment',role:'holding_owner',companyId:'company',branchId:null,departmentId:null,holdingId:'holding',holdingSlug:'holding',holdingName:'Holding',scope:{kind:'holding',holdingId:'holding',holdingSlug:'holding',holdingName:'Holding',companyId:'company'},assignmentScope:'holding',inherited:false,modules:['planning','manufacturing'],assignments:[],workspaces:[]};
function repository<Repository extends object>(facts:Partial<Repository>,calls:string[]):Repository{return new Proxy(facts,{get(target,name){if(name==='then')return undefined;if(name in target)return target[name as keyof Repository];if(typeof name==='string'&&/^(prepare|guard|lock)/.test(name))return ()=>{calls.push(name);return name;};return ()=>{throw new Error('Unexpected operation: '+String(name));};}})as Repository;}
function commands(calls:string[]){return {async replay<Result=Record<string,unknown>>():Promise<Result|null>{calls.push('replay');return null;},async commit<Result>(_actor:WorkContext,_key:string,operation:string,_input:unknown,_id:string,_version:number,result:Result,effects:string[]){calls.push(operation+':'+effects.join(','));return result;}};}
function resources(){const calls:string[]=[],ports:PlanningResourcePorts<string>={repository:repository<PlanningResourceRepository<string>>({},calls),commands:commands(calls),clock:{now:()=>42},requirePermission(a,p){calls.push(p);return a;}};return {calls,ports,app:createPlanningResourceApplication(ports)};}
const planInput={warehouseId:'warehouse',specificationId:'specification',specificationVersion:2,demandQuantity:'2',dueDate:'2026-10-01',capacityMinutes:10};
function planning(facts:Partial<PlanningScenarioRepository<string>>={}){const calls:string[]=[],ports:PlanningScenarioPorts<string>={repository:repository<PlanningScenarioRepository<string>>({async specification(){return {id:'specification',status:'approved',output_product_id:'output',batch_quantity_milli:1000};},async activeWarehouse(){return {id:'warehouse',branch_id:'branch'};},async specificationLines(){return {results:[{product_id:'material',quantity_milli:2000}]};},async availableStock(){return {available:1000,version:3};},async incomingSupply(){return {results:[{id:'purchase',version:2,incoming_milli:2000,due_date:'2026-10-01'}]};},async scopedRecommendation(){return {id:'recommendation',status:'proposed',version:1,created_by:'planner',scenario_id:'scenario',context_json:'{}',specification_id:'specification',specification_version:2,warehouse_id:'warehouse',branch_id:'branch',recommended_quantity_milli:2000};},...facts},calls),commands:commands(calls),clock:{now:()=>42},requirePermission(a,p){calls.push(p);return a;},async calculateCapacity(){calls.push('capacity');return null;},contextGuards(){calls.push('context');return ['context-guard'];}};return {calls,ports,app:createPlanningScenarioApplication(ports)};}
const specInput={name:'Reviewed output',mode:'bom',outputProductId:'output',batchQuantity:'1',expectedYieldBps:10000,lines:[{productId:'material',quantity:'2'}]};
function production(facts:Partial<ManufacturingProductionRepository<string>>={}){const calls:string[]=[],ports:ManufacturingProductionPorts<string>={repository:repository<ManufacturingProductionRepository<string>>({async specification(){return {id:'specification',status:'draft',version:1,created_by:'preparer'};},async scopedOrder(){return {id:'order',status:'planned',version:1,planned_quantity_milli:1000,batch_quantity_milli:1000,specification_id:'specification',warehouse_id:'warehouse',output_product_id:'output',output_tracking_mode:'none'};},async orderSpecificationLines(){return {results:[]};},...facts},calls),commands:commands(calls),clock:{now:()=>42},requirePermission(a,p){calls.push(p);return a;},async prepareAttachment(){calls.push('files');return {guards:['files-guard'],steps:['files']};},async preparePosting(){calls.push('finance');return {steps:['finance'],journalId:'journal'};},async prepareMaterialLots(){calls.push('material-lots');return null;},async prepareOutputLots(){calls.push('output-lots');return [];}};return {calls,ports,app:createManufacturingProductionApplication(ports)};}
const accountingInput={chartId:'chart',inventoryAccountId:'inventory',wipAccountId:'wip',laborAccountId:'labor',overheadAccountId:'overhead',scrapAccountId:'scrap'};
function accounting(facts:Partial<ManufacturingAccountingRepository<string>>={}){const calls:string[]=[],ports:ManufacturingAccountingPorts<string>={repository:repository<ManufacturingAccountingRepository<string>>({async activeChart(){return {base_currency:'THB'};},async profile(){return {id:'profile',status:'draft',version:1,created_by:'preparer'};},async approvedProfile(){return {id:'profile',version:2,chart_id:'chart',inventory_account_id:'inventory',wip_account_id:'wip',labor_account_id:'labor',overhead_account_id:'overhead',scrap_account_id:'scrap'};},async postingPeriod(){return {id:'period'};},...facts},calls),commands:commands(calls),clock:{now:()=>42},requirePermission(a,p){calls.push(p);return a;},async prepareJournal(_a,input){calls.push('journal:'+input.lines.map(l=>`${l.accountId}:${l.debit}:${l.credit}`).join(','));return {result:{id:'journal'},steps:['journal']};},async snapshotMoney(_a,input){calls.push('money:'+input.amountKind+':'+input.amountUnits);return {statement:'money'};}};return {calls,ports,app:createManufacturingAccountingApplication(ports)};}

describe('Planning resources preserve authority and current released capacity',()=>{
 test('requires both write and review authority before staging',async()=>{const f=resources();expect(await f.app.saveProductionResource(actor,null,{branchId:'branch',code:'CELL',name:'Assembly cell',dailyMinutes:60},'key')).toMatchObject({id:'production-resource-key',version:1});expect(f.calls.slice(0,3)).toEqual(['records.write','records.review','replay']);});
 test('department and non-planning roles never read owner facts',async()=>{for(const a of [{...actor,departmentId:'department'},{...actor,modules:['manufacturing']}]){const f=resources();await expect(f.app.saveProductionResource(a,null,{branchId:'branch',code:'CELL',name:'Assembly cell',dailyMinutes:60},'key')).rejects.toMatchObject({code:'PLANNING_RESOURCE_SCOPE'});expect(f.calls).toEqual(['records.write','records.review']);}});
 test('branch resource configuration cannot cross the current branch',async()=>{const f=resources();await expect(f.app.saveProductionResource({...actor,branchId:'other'},null,{branchId:'branch',code:'CELL',name:'Assembly cell',dailyMinutes:60},'key')).rejects.toMatchObject({code:'PLANNING_RESOURCE_SCOPE'});expect(f.calls.some(c=>c.startsWith('prepare'))).toBe(false);});
 test('a resource update needs a current version before staging a revision',async()=>{const f=resources();await expect(f.app.saveProductionResource(actor,'resource',{branchId:'branch',code:'CELL',name:'Assembly cell',dailyMinutes:60},'key')).rejects.toMatchObject({code:'VERSION_REQUIRED'});expect(f.calls).not.toContain('prepareResourceRevision');});
 test('calendar changes fence locked resource, current calendar and already released capacity together',async()=>{const f=resources();await f.app.saveProductionResourceCalendar(actor,'resource',{expectedVersion:0,resourceVersion:2,workDate:'2026-10-01',availableMinutes:0,reason:'Verified shutdown'},'key');expect(f.calls.at(-1)).toBe('planning.resource.calendar:lockResource,guardActiveResourceVersion,guardCalendarVersion,guardReleasedCapacity,prepareCalendar');});
 test('supplied context fences incoming and demand sources before capacity resources',()=>{const f=resources();expect(f.app.planningContextGuards(actor,'key',{demandSource:{id:'sales',version:2,quantityMilli:1000},incomingSupply:[{id:'purchase',version:3,productId:'product',quantityMilli:1000,dueDate:'2026-10-01'}],allocations:[{resourceId:'resource',workDate:'2026-10-01',minutes:60,resourceVersion:2,calendarVersion:1,availableMinutes:60}]})).toEqual(['lockSourceOrder','guardSourceOrderVersion','lockSourceOrder','guardSourceOrderVersion','lockAllocatedResource','guardAllocatedResourceVersion','guardAllocatedCalendarVersion']);});
});
describe('Planning scenarios use independently owned current facts',()=>{
 test('module denial happens before receipts and source reads',async()=>{const f=planning();await expect(f.app.createPlanningScenario({...actor,modules:['manufacturing']},planInput,'key')).rejects.toMatchObject({code:'MODULE_FORBIDDEN'});expect(f.calls).toEqual(['records.write']);});
 test('lost-response replay does not read changed source facts',async()=>{const f=planning();f.ports.commands.replay=async<Result>()=>({id:'prior'}as Result);expect(await f.app.createPlanningScenario(actor,planInput,'key')).toEqual({id:'prior'});expect(f.calls).toEqual(['records.write']);});
 test('withdrawn specification blocks new scenario before stock and capacity',async()=>{const f=planning({async specification(){return {status:'retired'};}});await expect(f.app.createPlanningScenario(actor,planInput,'key')).rejects.toMatchObject({code:'PLANNING_SOURCE_CHANGED'});expect(f.calls).not.toContain('capacity');});
 test('warehouse and source-order revisions remain scoped to the planner',async()=>{const missing=planning({async activeWarehouse(){return null;}});await expect(missing.app.createPlanningScenario(actor,planInput,'key')).rejects.toMatchObject({code:'WAREHOUSE_NOT_FOUND'});const changed=planning({async demandSource(){return null;}});await expect(changed.app.createPlanningScenario(actor,{...planInput,salesOrderId:'sales',salesOrderVersion:2},'key')).rejects.toMatchObject({code:'PLANNING_DEMAND_SOURCE_CHANGED'});});
 test('manual demand must be positive exact quantity',async()=>{const f=planning();await expect(f.app.createPlanningScenario(actor,{...planInput,demandQuantity:'0'},'key')).rejects.toMatchObject({code:'PLANNING_DEMAND_REQUIRED'});expect(f.calls).not.toContain('capacity');});
 test('shortages retain stock and captured supply without writing either owner',async()=>{const f=planning(),result=await f.app.createPlanningScenario(actor,planInput,'key');expect(result.shortages).toEqual([{productId:'material',requiredMilli:4000,availableMilli:1000,incomingMilli:2000,shortageMilli:1000}]);expect(result).toMatchObject({requiredMinutes:20,capacityMinutes:10,feasibleDate:'2026-10-02',context:{capacityBasis:'manual_capacity_assumption',stock:[{productId:'material',version:3}]}});expect(f.calls.at(-1)).toBe('planning.scenario.create:guardScenarioSpecification,context-guard,prepareScenario,prepareRecommendation,prepareCalculateEvent');});
 test('review rejects stale version and self review before capacity release',async()=>{for(const row of [{version:2,created_by:'planner'},{version:1,created_by:actor.userId}]){const f=planning({async scopedRecommendation(){return {status:'proposed',...row};}});await expect(f.app.reviewPlanningRecommendation(actor,'recommendation',{action:'approve',expectedVersion:1,reason:'Independent review'},'key')).rejects.toMatchObject({code:'CONFLICT'});expect(f.calls).not.toContain('prepareManufacturingOrder');}});
 test('independent recommendation release commits Planning and Manufacturing effects under one receipt',async()=>{const f=planning(),result=await f.app.reviewPlanningRecommendation(actor,'recommendation',{action:'approve',expectedVersion:1,reason:'Independent review'},'key');expect(result).toMatchObject({status:'approved',orderId:'mfg-order-key'});expect(f.calls.at(-1)).toBe('planning.recommendation.approve:lockRecommendation,guardIndependentRecommendation,prepareRecommendationReview,context-guard,guardRecommendationSpecification,prepareManufacturingOrder,prepareScenarioRelease,prepareReleaseEvent,prepareManufacturingReleaseEvent');});
 test('rejected recommendation does not reserve capacity or create an order',async()=>{const f=planning();expect(await f.app.reviewPlanningRecommendation(actor,'recommendation',{action:'reject',expectedVersion:1,reason:'Independent rejection'},'key')).toMatchObject({status:'rejected',orderId:null});expect(f.calls).not.toContain('context');expect(f.calls).not.toContain('prepareManufacturingOrder');});
});
describe('Manufacturing specifications and order transitions',()=>{
 test('duplicate material or output reused as material is rejected before effects',async()=>{for(const lines of [[specInput.lines[0],specInput.lines[0]],[{productId:'output',quantity:'1'}]]){const f=production();await expect(f.app.createSpecification(actor,{...specInput,lines},'key')).rejects.toMatchObject({code:'INVALID_SPECIFICATION_LINES'});expect(f.calls.some(c=>c.startsWith('prepare'))).toBe(false);}});
 test('specification and lines commit in source-before-lines order',async()=>{const f=production();await f.app.createSpecification(actor,specInput,'key');expect(f.calls.at(-1)).toBe('manufacturing.specification.create:guardOutputProduct,prepareSpecification,guardMaterialProduct,prepareSpecificationLine');});
 test('specification review retains independent approval and version fence',async()=>{const f=production({async specification(){return {status:'draft',version:1,created_by:actor.userId};}});await expect(f.app.reviewSpecification(actor,'specification',{action:'approve',expectedVersion:1,reason:'Independent review'},'key')).rejects.toMatchObject({code:'CONFLICT'});expect(f.calls).not.toContain('prepareSpecificationReview');});
 test('current order existence is checked before replay',async()=>{const f=production({async scopedOrder(){return null;}});await expect(f.app.changeManufacturingOrder(actor,'order',{action:'reserve',expectedVersion:1,expiresAt:1000,reason:'Reviewed reservation'},'key')).rejects.toMatchObject({code:'MANUFACTURING_ORDER_NOT_FOUND'});expect(f.calls).toEqual(['records.write']);});
 test('stale order cannot reserve material or obtain financial effects',async()=>{const f=production();await expect(f.app.changeManufacturingOrder(actor,'order',{action:'reserve',expectedVersion:2,expiresAt:1000,reason:'Reviewed reservation'},'key')).rejects.toMatchObject({code:'CONFLICT'});expect(f.calls).not.toContain('finance');expect(f.calls).not.toContain('lockOrder');});
 test('expired reservation is rejected using injected clock',async()=>{const f=production();await expect(f.app.changeManufacturingOrder(actor,'order',{action:'reserve',expectedVersion:1,expiresAt:42,reason:'Reviewed reservation'},'key')).rejects.toMatchObject({code:'INVALID_MANUFACTURING_TRANSITION'});expect(f.calls).not.toContain('prepareMaterialReservation');});
});
describe('Manufacturing independently approved cost map and WIP posting',()=>{
 test('WIP account must be separate from output and conversion accounts',async()=>{const f=accounting();await expect(f.app.createManufacturingAccountingProfile(actor,{...accountingInput,wipAccountId:'inventory'},'key')).rejects.toMatchObject({code:'MANUFACTURING_WIP_ACCOUNT'});expect(f.calls.some(c=>c.startsWith('prepare'))).toBe(false);});
 test('functional chart currency is checked before map creation',async()=>{const f=accounting({async activeChart(){return {base_currency:'USD'};}});await expect(f.app.createManufacturingAccountingProfile(actor,accountingInput,'key')).rejects.toMatchObject({code:'MANUFACTURING_CURRENCY_ADAPTER'});});
 test('account categories remain explicit domain facts',()=>{expect([0,1,2,3,4].map(manufacturingAccountKind)).toEqual(['asset','asset','conversion','conversion','scrap_expense']);});
 test('accounting review cannot approve its own prepared map',async()=>{const f=accounting({async profile(){return {status:'draft',version:1,created_by:actor.userId};}});await expect(f.app.reviewManufacturingAccountingProfile(actor,'profile',{action:'approve',expectedVersion:1,reason:'Independent review'},'key')).rejects.toMatchObject({code:'CONFLICT'});});
 test('missing approved map stops posting before Finance or money snapshots',async()=>{const f=accounting({async approvedProfile(){return null;}});await expect(f.app.prepareManufacturingPosting(actor,{key:'key',orderId:'order',orderVersion:2,phase:'issue',entryDate:'2026-10-01',material:100})).rejects.toMatchObject({code:'MANUFACTURING_ACCOUNTING_REQUIRED'});expect(f.calls).toEqual([]);});
 test('unsafe or negative costs cannot enter a journal',async()=>{for(const material of [-1,Number.MAX_SAFE_INTEGER+1]){const f=accounting();await expect(f.app.prepareManufacturingPosting(actor,{key:'key',orderId:'order',orderVersion:2,phase:'issue',entryDate:'2026-10-01',material})).rejects.toMatchObject({code:'MONEY_OVERFLOW'});expect(f.calls.some(c=>c.startsWith('journal'))).toBe(false);}});
 test('zero cost retains source guards without producing a financial journal',async()=>{const f=accounting();expect(await f.app.prepareManufacturingPosting(actor,{key:'key',orderId:'order',orderVersion:2,phase:'issue',entryDate:'2026-10-01'})).toEqual({steps:['guardApprovedProfile','guardFunctionalCurrency'],journalId:null});});
 test('issue debits WIP and freezes each positive conversion cost source',async()=>{const f=accounting(),result=await f.app.prepareManufacturingPosting(actor,{key:'key',orderId:'order',orderVersion:2,phase:'issue',entryDate:'2026-10-01',material:2000,labor:1001,overhead:200});expect(f.calls).toContain('journal:wip:32.01:0.00,inventory:0.00:20.00,labor:0.00:10.01,overhead:0.00:2.00');expect(f.calls.filter(c=>c.startsWith('money:'))).toEqual(['money:material_issue:2000','money:labor:1001','money:overhead:200']);expect(result.steps.slice(0,4)).toEqual(['guardApprovedProfile','guardFunctionalCurrency','journal','preparePostingEvidence']);});
 test('output and scrap independently relieve WIP into the selected destination',async()=>{for(const phase of ['output','scrap']as const){const f=accounting();await f.app.prepareManufacturingPosting(actor,{key:'key',orderId:'order',orderVersion:5,phase,entryDate:'2026-10-01',output:3201});expect(f.calls).toContain(`journal:${phase==='output'?'inventory':'scrap'}:32.01:0.00,wip:0.00:32.01`);}});
});
describe('Manufacturing tracked lot consumption and genealogy',()=>{
 test('untracked material requires no inventory lot facts',async()=>{const calls:string[]=[],app=createManufacturingLotApplication({repository:repository<ManufacturingLotRepository<string>>({},calls),clock:{now:()=>42}});expect(await app.prepareManufacturingMaterialLots(actor,{key:'key',orderId:'order',orderVersion:3,warehouseId:'warehouse',productId:'material',trackingMode:'none',requiredMilli:1000,entryDate:'2026-10-01',allocations:[]})).toBeNull();expect(calls).toEqual([]);});
 test('missing full lot allocation stops before staging lot effects',async()=>{const calls:string[]=[],app=createManufacturingLotApplication({repository:repository<ManufacturingLotRepository<string>>({},calls),clock:{now:()=>42}});await expect(app.prepareManufacturingMaterialLots(actor,{key:'key',orderId:'order',orderVersion:3,warehouseId:'warehouse',productId:'material',trackingMode:'lot',requiredMilli:1000,entryDate:'2026-10-01',allocations:[]})).rejects.toMatchObject({code:'MANUFACTURING_LOT_ALLOCATION_REQUIRED'});expect(calls).toEqual([]);});
 test('expired current lot cannot be consumed',async()=>{const calls:string[]=[],app=createManufacturingLotApplication({repository:repository<ManufacturingLotRepository<string>>({async materialLot(){return {status:'active',tracking_mode:'lot',balance_version:1,quantity_milli:1000,value_minor:100,expiry_date:'2026-09-30',held:0};}},calls),clock:{now:()=>42}});await expect(app.prepareManufacturingMaterialLots(actor,{key:'key',orderId:'order',orderVersion:3,warehouseId:'warehouse',productId:'material',trackingMode:'lot',requiredMilli:1000,entryDate:'2026-10-01',allocations:[{productId:'material',lotId:'lot',quantity:'1',balanceVersion:1}]})).rejects.toMatchObject({code:'MANUFACTURING_LOT_UNAVAILABLE'});expect(calls).toEqual([]);});
});

import {createElement} from 'react';
