vi.mock('next/navigation',()=>({useRouter:()=>({push:vi.fn(),replace:vi.fn(),refresh:vi.fn()}),usePathname:()=>'/holdings/acme/manufacturing',useSearchParams:()=>new URLSearchParams()}));
afterEach(()=>vi.unstubAllGlobals());
const activeManufacturing:ManufacturingPurchaseControls={newWork:true,settleExisting:true,history:true,revision:'opaque-production'},drainingManufacturing={...activeManufacturing,newWork:false},historyManufacturing={...drainingManufacturing,settleExisting:false};
test('Manufacturing separates active planning release and first reserve from retained issue QC and settlement',()=>{
 for(const input of [{entity:'specification'},{entity:'specification',action:'approve'},{entity:'scenario'},{entity:'recommendation',action:'approve'},{entity:'accounting',action:'approve'},{entity:'resource-calendar'},{entity:'resource'},{entity:'order',action:'reserve'}])expect(manufacturingCommandAllowed(drainingManufacturing,input)).toBe(false);
 for(const input of [{entity:'specification',action:'retire'},{entity:'scenario',action:'cancel'},{entity:'recommendation',action:'reject'},{entity:'resource',id:'resource',status:'archived'},...['issue','report','pass-qc','fail-qc','rework','scrap','complete-operation','cancel'].map(action=>({entity:'order',action}))]){expect(manufacturingCommandAllowed(drainingManufacturing,input)).toBe(true);expect(manufacturingCommandAllowed(historyManufacturing,input)).toBe(false);}
 expect(manufacturingCommandAllowed(undefined,{entity:'order',action:'issue'})).toBe(true);for(const input of [null,{},[],{entity:'unknown'},{entity:'order',action:'unregistered'}])expect(manufacturingCommandAllowed(activeManufacturing,input)).toBe(false);
});
test('Manufacturing network and incomplete acknowledgements retain one exact original command identity',async()=>{
 const keys:string[]=[],request=createManufacturingCommandFetch(async(_url,init)=>{keys.push(new Headers(init?.headers).get('Idempotency-Key')!);if(keys.length===1)throw Error('Lost original production response');if(keys.length===2)return new Response('truncated');if(keys.length===3)return Response.json({data:{id:'order'}});if(keys.length===4)return Response.json({data:{id:'order',version:0}});return Response.json({data:{id:'order',version:3}});}),input={method:'POST',body:'{"entity":"order","id":"order","action":"issue","expectedVersion":2}'};
 await expect(request('/production',input)).rejects.toThrow('Lost original production response');for(let i=0;i<3;i++)await request('/production',input);expect(request.hasAttempt('/production',input.body)).toBe(true);await request('/production',input);expect(request.hasAttempt('/production',input.body)).toBe(false);await request('/production',input);expect(new Set(keys.slice(0,5)).size).toBe(1);expect(keys[5]).not.toBe(keys[0]);
});
test('Uncertain production changes retain original Company role payload and captured form while later edits wait',()=>{
 const attempts=createManufacturingCommandAttempt(),completion={form:{} as HTMLFormElement,formEditVersion:'submitted'},original:ManufacturingCommandAttempt={path:'',body:'original issue',create:false,context:'Company:Manufacturing:1',completion};attempts.unresolved(original);expect(()=>attempts.select({...original,body:'newer report'},original.context)).toThrow('Retry the submitted production change first');expect(()=>attempts.select(original,'different role')).toThrow('workspace changed');expect(attempts.select({...original,completion:{...completion,formEditVersion:'later'}},original.context)).toBe(original);expect(attempts.retry()?.completion?.formEditVersion).toBe('submitted');attempts.resolved(original);expect(attempts.select({...original,body:'newer report'},original.context).body).toBe('newer report');
});
test('Only parsed positive production receipts acknowledge the captured revision and leave later edits dirty',async()=>{
 const form={isConnected:true,getAttribute:()=>'later-output'} as unknown as HTMLFormElement,completion={form,formEditVersion:'submitted'},events:Event[]=[];vi.stubGlobal('window',{dispatchEvent:(event:Event)=>{events.push(event);return true;}});await createManufacturingCommandFetch(async()=>Response.json({data:{id:'order',version:3}}))('/production',{body:'submitted'},completion);const saved=events.find(event=>event.type==='erpx:record-command-saved') as CustomEvent;expect(saved.detail.manufacturingAcknowledged).toBe(true);expect(saved.detail.formEditVersion).toBe('submitted');expect(manufacturingFormUnchanged(saved.detail)).toBe(false);for(const value of [null,{},[],{id:''},{id:'order'},{id:'order',version:0},{id:'order',version:1.5}])expect(validManufacturingAcknowledgement(value)).toBe(false);
});
test('Manufacturing server content provides current-page editor triggers without serializing owner purchase or IAM facts',()=>{
 const data={specifications:[],plans:[],recommendations:[],orders:[],products:[],warehouses:[],resources:[],calendar:[],accountingProfiles:[],demandSources:[],accounts:[],canConfigureAccounting:false,canReviewAccounting:false,canManageResources:false,canWriteProduction:true,canReviewProduction:true,purchase:drainingManufacturing,recordPurchases:{},advancedPurchase:historyManufacturing};
 const html=renderToStaticMarkup(createElement(ProductionConsole,{base:'/holdings/acme',module:'manufacturing',data}));expect(html).toContain('Draft BOM or formula');expect(html).toContain('disabled');expect(html).not.toContain('name="batchQuantity"');const planning=renderToStaticMarkup(createElement(ProductionConsole,{base:'/holdings/acme',module:'planning',data}));expect(planning).toContain('Calculate plan');expect(planning).not.toContain('name="comparisonScenarioId"');for(const secret of ['company_package_grants','assignment_permissions','authority_json','context_json'])expect(html+planning).not.toContain(secret);
});


import {ManufacturingPostingSetup,ManufacturingPostingFields} from '@erpx/feature-manufacturing/components/posting-setup';
import {createManufacturingPostingCommands,manufacturingPostingAccountFields,validManufacturingPostingSetup,type ManufacturingPostingSource} from '@erpx/feature-manufacturing/lib/posting-setup-command';
import type {ManufacturingPostingSetupInput,ManufacturingPostingSetupView} from '@erpx/server-manufacturing/public/posting-setup';
