test.each(['post','refresh'] as const)('Manufacturing %s original-body context loss retains exact original key/body and first completion until recovery',async phase=>{
 const browser=mfgPostingBrowser(),source:ManufacturingPostingSource={base:'/holdings/acme',companyId:'company',contextKey:mfgPostingInput.contextKey};let release!:()=>void,started!:()=>void,first=true;const ready=new Promise<void>(resolve=>{started=resolve;}),pause=new Promise<void>(resolve=>{release=resolve;});class OriginalBody extends Response{override async json(){started();await pause;return super.json();}}
 const network=vi.fn<(url:RequestInfo|URL,init?:RequestInit)=>Promise<Response>>(async(_url,init)=>{const post=init?.method==='POST',value={data:post?{id:'company',status:'configured',version:1}:mfgPostingView(true)};if(first&&post===(phase==='post')){first=false;return new OriginalBody(JSON.stringify(value));}return Response.json(value);});vi.stubGlobal('fetch',network);const commands=createManufacturingPostingCommands(()=>source);
 try{const pending=commands.submit(mfgPostingInput);await ready;browser.node.dataset.workStale='true';release();await expect(pending).rejects.toMatchObject({code:'WORK_CONTEXT_CHANGED'});expect(commands.pending()).toBe(true);expect(browser.events).toEqual([]);browser.node.dataset.workStale='false';const replay=await commands.retry();expect(replay.acknowledge()).toBe(true);const posts=network.mock.calls.filter(([,init])=>init?.method==='POST');expect(new Set(posts.map(([,init])=>new Headers(init?.headers).get('Idempotency-Key'))).size).toBe(1);expect(posts.every(([,init])=>init?.body===JSON.stringify(mfgPostingInput))).toBe(true);}finally{release();}
});
