function mfgSetupController(){for(const port of Object.values(mfgSetupPorts))port.mockReset();mfgSetupPorts.actor.mockResolvedValue(actor);mfgSetupPorts.read.mockResolvedValue(mfgPostingView());mfgSetupPorts.prerequisites.mockResolvedValue(mfgPrerequisites());mfgSetupPorts.profiles.mockResolvedValue(mfgProfiles());}
