const mfgSetupRequest=(body:unknown,origin='https://manufacturing.example.test',key='original-key')=>new Request('https://manufacturing.example.test/api/v1/holdings/acme/production/posting-setup',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json',...(key?{'Idempotency-Key':key}:{})},body:JSON.stringify(body)});
test('Manufacturing dedicated page and exact GET compose three owner views directly with private cache and no generic workspace',async()=>{
 mfgSetupController();const page=await ManufacturingSetupPage({params:Promise.resolve({holdingSlug:'acme'})});expect(page.props.initial).toEqual(mfgPostingView());expect(page.props.initialPrerequisites).toEqual(mfgPrerequisites());expect(page.props.initialProfiles).toEqual(mfgProfiles());for(const port of [mfgSetupPorts.read,mfgSetupPorts.prerequisites,mfgSetupPorts.profiles])expect(port).toHaveBeenCalledExactlyOnceWith(actor);
 const response=await mfgPostingGET(new Request('https://manufacturing.example.test/'),mfgSetupContext());expect(response.status).toBe(200);expect(response.headers.get('Cache-Control')).toBe('private, no-store');expect(await response.json()).toEqual({data:mfgPostingView()});
 for(const part of ['prerequisites','profiles']){const response=await mfgPreparationGET(new Request('https://manufacturing.example.test/'),mfgSetupContext([part]));expect(response.status).toBe(200);expect(response.headers.get('Cache-Control')).toBe('private, no-store');}
});
test('Manufacturing exact POST preserves mapping/profile body-key and original independent review envelope; invalid selectors/origin/schema never call owners',async()=>{
 mfgSetupController();mfgSetupPorts.initialize.mockResolvedValue({id:'company',status:'configured',version:1});const mapping=await mfgPostingPOST(mfgSetupRequest(mfgPostingInput),mfgSetupContext());expect(mapping.status).toBe(201);expect(mfgSetupPorts.initialize).toHaveBeenCalledExactlyOnceWith(actor,mfgPostingInput,'original-key');
 const profile={contextKey:'d'.repeat(64),input:mfgProfileInput};mfgSetupPorts.prepare.mockResolvedValue({id:'mfg-accounting-original-key',status:'draft',version:1});expect((await mfgPreparationPOST(mfgSetupRequest(profile),mfgSetupContext(['profiles']))).status).toBe(201);expect(mfgSetupPorts.prepare).toHaveBeenCalledExactlyOnceWith(actor,profile,'original-key');
 const decision={contextKey:'d'.repeat(64),input:{expectedVersion:2,action:'retire',reason:'Independent existing closure'}};mfgSetupPorts.decide.mockResolvedValue({id:'profile',status:'retired',version:3});const response=await mfgPreparationPOST(mfgSetupRequest(decision),mfgSetupContext(['profiles','profile','decide']));expect(response.status).toBe(200);expect(response.headers.get('Cache-Control')).toBe('private, no-store');expect(mfgSetupPorts.decide).toHaveBeenCalledExactlyOnceWith(actor,'profile',decision,'original-key');
 for(const parts of [['prerequisites'],['charts','extra'],['profiles','profile'],['profiles','profile','approve']])expect((await mfgPreparationPOST(mfgSetupRequest({}),mfgSetupContext(parts))).status).toBe(404);
 expect((await mfgPreparationGET(new Request('https://manufacturing.example.test/'),mfgSetupContext(['profiles','profile']))).status).toBe(404);expect((await mfgPreparationPOST(mfgSetupRequest(profile,'https://other.example.test'),mfgSetupContext(['profiles']))).status).toBe(403);expect((await mfgPreparationPOST(mfgSetupRequest(profile,undefined,''),mfgSetupContext(['profiles']))).status).toBe(422);expect((await mfgPreparationPOST(mfgSetupRequest({...profile,extra:'not-allowed'}),mfgSetupContext(['profiles']))).status).toBe(422);expect(mfgSetupPorts.prepare).toHaveBeenCalledTimes(1);expect(mfgSetupPorts.decide).toHaveBeenCalledTimes(1);
});

